@Injectable({ providedIn: 'root' })
export class DashboardService {
  private readonly salesApi = inject(SalesApiService);
  private readonly ticketsApi = inject(TicketsApiService);

  private readonly sales = signal<SalesPoint[]>([]);
  private readonly openTickets = signal<Ticket[]>([]);

  readonly monthlyRevenue = computed(() =>
    this.sales().reduce((sum, point) => sum + point.amount, 0)
  );

  readonly urgentTickets = computed(() =>
    this.openTickets().filter(t => t.priority === 'high').length
  );

  loadDashboard(): void {
    this.salesApi.getRecent().subscribe(points => this.sales.set(points));
    this.ticketsApi.getOpen().subscribe(tickets => this.openTickets.set(tickets));
  }
}

